        #[derive(serde::Serialize, serde::Deserialize, Clone, Debug)]
        pub struct WeatherResponse {
            pub temp: f64,
            pub source: String,
        }

        pub(crate) async fn fetch_london_weather() -> Option<(f64, String)> {
            let client = reqwest::Client::builder()
                .user_agent("AlexsTube/1.0.0 (contact: point@gemini.com)")
                .build()
                .ok()?;

            let mut temp1 = None;
            if let Ok(resp) = client.get("https://api.open-meteo.com/v1/forecast?latitude=51.5074&longitude=-0.1278&current_weather=true").send().await {
                if let Ok(json) = resp.json::<serde_json::Value>().await {
                    if let Some(t) = json.get("current_weather").and_then(|cw| cw.get("temperature")).and_then(|v| v.as_f64()) {
                        temp1 = Some(t);
                    }
                }
            }

            let mut temp2 = None;
            if let Ok(resp) = client.get("https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=51.5074&lon=-0.1278").send().await {
                if let Ok(json) = resp.json::<serde_json::Value>().await {
                    if let Some(t) = json.get("properties")
                        .and_then(|p| p.get("timeseries"))
                        .and_then(|ts| ts.as_array())
                        .and_then(|arr| arr.first())
                        .and_then(|f| f.get("data"))
                        .and_then(|d| d.get("instant"))
                        .and_then(|i| i.get("details"))
                        .and_then(|det| det.get("air_temperature"))
                        .and_then(|v| v.as_f64()) {
                        temp2 = Some(t);
                    }
                }
            }

            match (temp1, temp2) {
                (Some(t1), Some(t2)) => {
                    let avg = (t1 + t2) / 2.0;
                    Some((
                        avg,
                        format!("Avg of Open-Meteo ({:.1}°C) & Yr.no ({:.1}°C)", t1, t2),
                    ))
                }
                (Some(t), None) => Some((t, "Open-Meteo".to_string())),
                (None, Some(t)) => Some((t, "Yr.no".to_string())),
                _ => None,
            }
        }

        pub(crate) async fn get_weather(
            State(state): State<AppState>,
        ) -> Json<ApiResponse<Option<WeatherResponse>>> {
            let w = state.weather.load();
            let res = w.as_ref().as_ref().map(|t| WeatherResponse {
                temp: t.0,
                source: t.1.clone(),
            });
            Json(ApiResponse::success(res))
        }

